{
  "segment_function": "Introduce three types of artificial adaptation (carapace, prosthesis, and enclosure) in response to degrading environmental conditions, focusing first on the carapace.",
  "claims": [
    {
      "claim": "Environmental deterioration including unhealthy outdoor air, heat, and extreme weather will lead people to adopt various forms of artifice to move and breathe.",
      "claim_type": "author_position",
      "supporting_excerpt": "What forms of arti ﬁce are people likely to reach for to make it easier to “move and breathe ” under these conditions? One signi ﬁcant part of the answer is that it will depend on who they are, where and under what political circumstances they live, and where they stand in the interlocking inequalities of wealth, health, power, and regard that already stratify the globe.",
      "support_kind": "direct",
      "qualifications": [
        "depends on who people are, where they live under political circumstances, and their standing in interlocking inequalities"
      ],
      "confidence": 1
    },
    {
      "claim": "The carapace refers to protective equipment and material designed to insulate human bodies from a hostile atmosphere, aligning with the neoliberal tendency to privatize public problems into individual resilience.",
      "claim_type": "author_position",
      "supporting_excerpt": "The ﬁrst is in some ways the simplest, for it hews closest to the human body ,\nand is readily conformable to the neoliberal tendency to convert public prob-\nlems into challenges to individual resourcefulness and resilience. I call this the\n“carapace,” using the term broadly to refer to a wide range of protective\nequipment and material designed to insulate human bodies from an increas-\ningly hostile atmosphere.",
      "support_kind": "direct",
      "qualifications": [
        "hew closest to the human body",
        "conformable to the neoliberal tendency"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "carapace",
      "definition": "A wide range of protective equipment and material designed to insulate human bodies from an increasingly hostile atmosphere."
    }
  ],
  "distinctions": [],
  "unresolved_context": [
    "Discussion of prosthesis and enclosure types of adaptation continues in subsequent blocks."
  ],
  "must_not_be_lost": [
    "The choice of adaptation depends heavily on preexisting global inequalities of wealth, health, power, and regard."
  ]
}

